from itertools import product
from typing import List, Tuple


def holonomy_mod2(flips: List[int]) -> int:
    """Parity of the number of orientation flips around the loop."""
    return sum(flips) % 2


def classify_band(flips: List[int]) -> str:
    """Orientable iff holonomy in Z/2 vanishes."""
    return "orientable (cylinder)" if holonomy_mod2(flips) == 0 \
        else "non-orientable (Moebius)"


def enumerate_bands(n: int) -> List[Tuple[Tuple[int, ...], int, str]]:
    """All flip patterns on n overlaps with their class and holonomy."""
    rows = []
    for flips in product((0, 1), repeat=n):
        rows.append((flips, holonomy_mod2(list(flips)), classify_band(list(flips))))
    return rows


if __name__ == "__main__":
    for flips, h, kind in enumerate_bands(3):
        print(f"flips={flips}  holonomy(Z/2)={h}  ->  {kind}")

import random
from collections import defaultdict
from typing import Dict, List


def holonomy(t: List[int]) -> int:
    return sum(t)


def coboundary(h: List[int]) -> List[int]:
    n = len(h)
    return [h[(i + 1) % n] - h[i] for i in range(n)]


def gauge_from_partial_sums(t: List[int]) -> List[int]:
    h = [0]
    for k in range(len(t) - 1):
        h.append(h[-1] + t[k])
    return h


def classify(figures: List[List[int]]) -> Dict[int, List[List[int]]]:
    """Bucket figures by holonomy; each bucket is one cohomology class."""
    classes: Dict[int, List[List[int]]] = defaultdict(list)
    for t in figures:
        classes[holonomy(t)].append(t)
    return classes


if __name__ == "__main__":
    random.seed(0)
    n = 4
    figs = [[random.randint(-3, 3) for _ in range(n)] for _ in range(12)]
    classes = classify(figs)
    for hol, members in sorted(classes.items()):
        print(f"class holonomy={hol}: {len(members)} figures")
        a, b = members[0], members[-1]
        diff = [x - y for x, y in zip(a, b)]
        assert coboundary(gauge_from_partial_sums(diff)) == diff
    print("All within-class differences are coboundaries (verified).")

