function REALIZABLE(t[0..n-1], zero):
    acc <- zero
    for i in 0..n-1:
        acc <- acc + t[i]        # accumulate increments around the cycle
    return (acc == zero)          # exactness: coboundary iff zero holonomy

function GAUGE(t[0..n-1], zero):
    assert HOLONOMY(t) == zero        # precondition for closure
    h[0] <- zero
    for i in 1..n-1:
        h[i] <- h[i-1] + t[i-1]        # partial sums
    return h                           # satisfies (delta h)_i = t_i

function COHOMOLOGOUS(t[0..n-1], s[0..n-1]):
    if HOLONOMY(t) != HOLONOMY(s):
        return (False, none)
    d[i] <- t[i] - s[i]  for all i        # zero-holonomy difference
    h <- GAUGE(d)                          # coboundary witness
    return (True, h)

