from typing import List, Optional, Tuple


def holonomy(t: List[int], modulus: Optional[int] = None) -> int:
    s = sum(t)
    return s % modulus if modulus is not None else s


def gauge_from_partial_sums(t: List[int]) -> List[int]:
    h = [0]
    for k in range(len(t) - 1):
        h.append(h[-1] + t[k])
    return h


def cohomologous(t: List[int], s: List[int],
                 modulus: Optional[int] = None) -> Tuple[bool, Optional[List[int]]]:
    """Same H^1 class iff equal holonomy; returns a coboundary witness."""
    if holonomy(t, modulus) != holonomy(s, modulus):
        return (False, None)
    diff = [ti - si for ti, si in zip(t, s)]
    return (True, gauge_from_partial_sums(diff))
